type agreementNeutralAliasHeadingSource struct {
	Original, PrivateReading    agreementNeutralHeadingSource
	Native, PrivateNative       agreementNativeHeadingSource
	IDs, PrivateIDs             []string
	Private                     string
	OriginalSpan, ProjectedSpan graph.Span
	Ordinal                     int
	Valid                       bool
}

// An exposed alias can name a heading without changing its link target. Both
// grammars must bind its original display byte and the whole name allocation
// before that alias can own a missing check name.
func agreementNeutralAliasHeadingReading(body string, f *agreementFailure, page *agreementHTML) agreementNeutralAliasHeadingSource {
	r := agreementNeutralAliasHeadingSource{Ordinal: -1}
	if f == nil || page == nil || f.Property != "P4" || f.Identity != "literal-heading-id" || f.Direction != "page-only" || f.Multiplicity != 1 || f.Tuple != (agreementCitation{}) || !f.PagePresent || f.JudgeAccepted || f.ExcerptFound || f.Cut != "" || strings.Contains(body, "q") {
		return r
	}
	r.Original = agreementNeutralHeadingRead(body)
	a := &r.Original
	if !a.Valid || !slices.Equal(a.IDs, page.Headings) || a.Native.Names[f.Fragment] {
		return r
	}
	r.IDs, r.Native = a.IDs, a.Native
	for i, id := range r.IDs {
		if id == f.Fragment {
			if r.Ordinal >= 0 {
				return r
			}
			r.Ordinal = i
		}
	}
	if r.Ordinal < 0 || r.Ordinal >= len(a.Page.Headings) {
		return r
	}
	span := a.Page.Headings[r.Ordinal]
	if span.Start < 0 || span.Stop <= span.Start || span.Stop > len(a.Positions) {
		return r
	}
	found := -1
	for _, field := range a.Page.Fields {
		fs := field.Span
		if field.Role != "live" || fs.Start < span.Start || fs.Stop > span.Stop || fs.Stop-fs.Start != 11 || a.Projected[fs.Start:fs.Stop] != "[[A|alias]]" {
			continue
		}
		at := fs.Start + 4
		protected := false
		for _, code := range a.Page.Code {
			if code.Start <= at && at < code.Stop {
				protected = true
			}
		}
		if !protected {
			found = at
			break
		}
	}
	if found < 0 {
		return r
	}
	r.ProjectedSpan = graph.Span{Start: found, Stop: found + 1}
	start := a.Positions[found]
	if start < 0 || start >= len(body) || body[start] != a.Projected[found] {
		return r
	}
	r.OriginalSpan = graph.Span{Start: start, Stop: start + 1}
	private := []byte(body)
	private[start] = 'q'
	r.Private = string(private)
	r.PrivateReading = agreementNeutralHeadingRead(r.Private)
	b := &r.PrivateReading
	if !b.Valid || !slices.Equal(a.Positions, b.Positions) || !slices.Equal(a.Native.Check.Targets, b.Native.Check.Targets) {
		return r
	}
	expected := []byte(a.Projected)
	expected[found] = 'q'
	if string(expected) != b.Projected || !cmp.Equal(a.Page.Headings, b.Page.Headings) || !cmp.Equal(a.Page.Code, b.Page.Code) || !cmp.Equal(a.Page.Fields, b.Page.Fields) || len(a.Page.Bases) != len(b.Page.Bases) || len(a.Page.Checks) != len(b.Page.Checks) {
		return r
	}
	for i := range a.Page.Bases {
		if i == r.Ordinal {
			if a.Page.Bases[i] == b.Page.Bases[i] || a.Page.Checks[i] == b.Page.Checks[i] {
				return r
			}
		} else if a.Page.Bases[i] != b.Page.Bases[i] || a.Page.Checks[i] != b.Page.Checks[i] {
			return r
		}
	}
	r.PrivateIDs, r.PrivateNative = b.IDs, b.Native
	r.Valid = true
	return r
}
func agreementNeutralAliasHeadingEquation(ids []string, names map[string]bool, failures []agreementFailure) bool {
	expected := map[string]int{}
	for _, id := range ids {
		if !names[id] {
			f := agreementFailure{Property: "P4", Identity: "literal-heading-id", Fragment: id, Direction: "page-only", Multiplicity: 1, PagePresent: true}
			expected[agreementSignature(&f)]++
		}
	}
	actual := map[string]int{}
	for i := range failures {
		f := &failures[i]
		if f.Property == "P4" {
			actual[agreementSignature(f)]++
		}
	}
	return maps.Equal(expected, actual)
}
func agreementNeutralAliasHeadingProjection(source *agreementNeutralAliasHeadingSource, before, after []agreementFailure, page, privatePage *agreementHTML, diagnostics, privateDiagnostics []render.Diagnostic) bool {
	if source == nil || page == nil || privatePage == nil || !source.Valid || !slices.Equal(source.IDs, page.Headings) || !slices.Equal(source.PrivateIDs, privatePage.Headings) || !cmp.Equal(diagnostics, privateDiagnostics) || !agreementNeutralAliasHeadingEquation(source.IDs, source.Native.Names, before) || !agreementNeutralAliasHeadingEquation(source.PrivateIDs, source.PrivateNative.Names, after) {
		return false
	}
	a, b := *page, *privatePage
	a.Headings = nil
	b.Headings = nil
	if !cmp.Equal(a, b) {
		return false
	}
	original, private := map[string]int{}, map[string]int{}
	for i := range before {
		f := &before[i]
		if f.Property != "P4" {
			original[agreementSignature(f)]++
		}
	}
	for i := range after {
		f := &after[i]
		if f.Property != "P4" {
			private[agreementSignature(f)]++
		}
	}
	return maps.Equal(original, private)
}
func agreementNeutralAliasHeadingDifference(c agreementCase, f *agreementFailure, html string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 {
		return "", "", ""
	}
	for i := range agreementNeutralAliasHeadingDeclarations() {
		r := &agreementNeutralAliasHeadingDeclarations()[i]
		if c.Body != r.Body || agreementSignature(f) != r.Selected {
			continue
		}
		if html != r.HTML || !cmp.Equal(*page, r.Page) || !cmp.Equal(diagnostics, r.Diagnostics) || !maps.Equal(agreementMixedCurrent(failures), agreementMixedCurrent(r.Before)) {
			return "", "", ""
		}
		source := agreementNeutralAliasHeadingReading(c.Body, f, page)
		if !cmp.Equal(source, r.Source) || !agreementNeutralAliasHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
			return "", "", ""
		}
		return "debt", "#1011 stage 8", "judge"
	}
	return "", "", ""
}
func agreementNeutralAliasHeadingSelected(t *testing.T, r *agreementNeutralAliasHeadingDeclaration) agreementFailure {
	t.Helper()
	var selected agreementFailure
	seen := 0
	for i := range r.Before {
		f := &r.Before[i]
		if agreementSignature(f) == r.Selected {
			selected = *f
			seen++
		}
	}
	if seen != 1 {
		t.Fatal("caught: unique neutral alias heading declaration")
	}
	return selected
}
func TestAgreementNeutralAliasHeadingOwnedSource(t *testing.T) {
	rows := agreementNeutralAliasHeadingDeclarations()
	if len(rows) != 5 {
		t.Fatal("caught: complete neutral alias heading declaration set")
	}
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			selected := agreementNeutralAliasHeadingSelected(t, r)
			source := agreementNeutralAliasHeadingReading(r.Body, &selected, &r.Page)
			if !source.Valid || !cmp.Equal(source, r.Source) || source.Private != r.Private {
				t.Fatalf("caught: complete neutral alias heading physical source and whole namespace (-want +got):\n%s", cmp.Diff(r.Source, source))
			}
			span := source.OriginalSpan
			private := []byte(r.Body)
			if span.Start < 0 || span.Stop > len(private) || span.Stop <= span.Start {
				t.Fatal("caught: physical neutral alias heading interval")
			}
			copy(private[span.Start:span.Stop], strings.Repeat("q", span.Stop-span.Start))
			if string(private) != r.Private || source.Ordinal < 0 || source.IDs[source.Ordinal] != selected.Fragment || !agreementNeutralAliasHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
				t.Fatal("caught: complete neutral alias heading signed source projection")
			}
		})
	}
}
func TestAgreementNeutralAliasHeadingOwnedPublic(t *testing.T) {
	for i := range agreementNeutralAliasHeadingDeclarations() {
		r := &agreementNeutralAliasHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			raw, page, before := agreementProseP0Failures(t, r.Body)
			pr, pp, after := agreementProseP0Failures(t, r.Private)
			if raw.HTML != r.HTML || pr.HTML != r.PrivateHTML || !cmp.Equal(page, r.Page) || !cmp.Equal(pp, r.PrivatePage) || !cmp.Equal(raw.Diagnostics, r.Diagnostics) || !cmp.Equal(pr.Diagnostics, r.PrivateDiagnostics) || !maps.Equal(agreementMixedCurrent(before), agreementMixedCurrent(r.Before)) || !maps.Equal(agreementMixedCurrent(after), agreementMixedCurrent(r.After)) || !agreementNeutralAliasHeadingProjection(&r.Source, before, after, &page, &pp, raw.Diagnostics, pr.Diagnostics) {
				t.Fatal("caught: complete neutral alias heading public and diagnostic ledgers")
			}
			selected := agreementNeutralAliasHeadingSelected(t, r)
			k, a, w := agreementNeutralAliasHeadingDifference(agreementCase{Body: r.Body}, &selected, raw.HTML, &page, raw.Diagnostics, before)
			if k != "debt" || a != "#1011 stage 8" || w != "judge" {
				t.Fatal("caught: exact neutral alias heading authority and original source membership")
			}
		})
	}
}
func TestAgreementNeutralAliasHeadingOwnedRefusals(t *testing.T) {
	for i := range agreementNeutralAliasHeadingDeclarations() {
		r := &agreementNeutralAliasHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			f := agreementNeutralAliasHeadingSelected(t, r)
			refuse := func(c agreementCase, x *agreementFailure, html string, page *agreementHTML, ds []render.Diagnostic, fs []agreementFailure) {
				t.Helper()
				k, a, w := agreementNeutralAliasHeadingDifference(c, x, html, page, ds, fs)
				if k != "" || a != "" || w != "" {
					t.Fatal("caught: neutral alias heading refuses changed complete source or context")
				}
			}
			for _, c := range []agreementCase{{Body: r.Body + "!"}, {Body: r.Body, Title: "outside"}, {Body: r.Body, Companions: capturedBodies{"outside.md": "outside"}}} {
				refuse(c, &f, r.HTML, &r.Page, r.Diagnostics, r.Before)
			}
			c := agreementCase{Body: r.Body}
			refuse(c, nil, r.HTML, &r.Page, r.Diagnostics, r.Before)
			refuse(c, &f, r.HTML, nil, r.Diagnostics, r.Before)
			refuse(c, &f, r.HTML+"!", &r.Page, r.Diagnostics, r.Before)
			changes := []func(*agreementFailure){func(f *agreementFailure) { f.Property = "outside" }, func(f *agreementFailure) { f.Identity = "outside" }, func(f *agreementFailure) { f.Fragment = "outside" }, func(f *agreementFailure) { f.Direction = "judge-only" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Tuple.SourceRole = "outside" }, func(f *agreementFailure) { f.Tuple.Target = "outside" }, func(f *agreementFailure) { f.Tuple.Section = "outside" }, func(f *agreementFailure) { f.Tuple.State = "outside" }, func(f *agreementFailure) { f.PagePresent = false }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true }, func(f *agreementFailure) { f.Cut = "outside" }}
			for _, change := range changes {
				x := f
				change(&x)
				refuse(c, &x, r.HTML, &r.Page, r.Diagnostics, r.Before)
			}
			altered := r.Page
			altered.Headings = append(slices.Clone(r.Page.Headings), "outside")
			refuse(c, &f, r.HTML, &altered, r.Diagnostics, r.Before)
			altered = r.Page
			altered.Citations = append(slices.Clone(r.Page.Citations), agreementCitation{Target: "outside"})
			refuse(c, &f, r.HTML, &altered, r.Diagnostics, r.Before)
			ds := append(slices.Clone(r.Diagnostics), render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
			refuse(c, &f, r.HTML, &r.Page, ds, r.Before)
			for j := range r.Before {
				fs := slices.Delete(slices.Clone(r.Before), j, j+1)
				refuse(c, &f, r.HTML, &r.Page, r.Diagnostics, fs)
				if agreementNeutralAliasHeadingProjection(&r.Source, fs, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
					t.Fatal("caught: every original neutral alias heading receipt retained")
				}
			}
			for j := range r.After {
				fs := slices.Delete(slices.Clone(r.After), j, j+1)
				if agreementNeutralAliasHeadingProjection(&r.Source, r.Before, fs, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
					t.Fatal("caught: every private neutral alias heading receipt retained")
				}
			}
			source := r.Source
			source.IDs = append(slices.Clone(r.Source.IDs), "outside")
			if agreementNeutralAliasHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
				t.Fatal("caught: whole neutral alias heading source allocation retained")
			}
		})
	}
}
func TestAgreementNeutralAliasHeadingOwnedCensus(t *testing.T) {
	rows := agreementNeutralAliasHeadingProspects()
	if len(rows) != 326 {
		t.Fatal("caught: whole neutral alias heading prospect roster")
	}
	qualified := map[[2]string]bool{}
	for i := range rows {
		r := &rows[i]
		raw, page, before := agreementProseP0Failures(t, r.Body)
		var selected agreementFailure
		seen := 0
		for j := range before {
			f := &before[j]
			if agreementSignature(f) == r.Selected {
				selected = *f
				seen++
			}
		}
		if seen != 1 {
			t.Fatal("caught: every original neutral alias heading prospect exists")
		}
		source := agreementNeutralAliasHeadingReading(r.Body, &selected, &page)
		eligible := false
		if source.Valid {
			pr, pp, after := agreementProseP0Failures(t, source.Private)
			eligible = agreementNeutralAliasHeadingProjection(&source, before, after, &page, &pp, raw.Diagnostics, pr.Diagnostics)
		}
		if eligible != r.Eligible {
			t.Fatalf("caught: whole neutral alias heading eligibility and refusal set case=%s selected=%s got=%t want=%t", r.Case, r.Selected, eligible, r.Eligible)
		}
		if eligible {
			qualified[[2]string{r.Body, r.Selected}] = true
		}
	}
	declared := map[[2]string]bool{}
	for i := range agreementNeutralAliasHeadingDeclarations() {
		r := &agreementNeutralAliasHeadingDeclarations()[i]
		declared[[2]string{r.Body, r.Selected}] = true
	}
	if len(declared) != 5 || !maps.Equal(qualified, declared) {
		t.Fatal("caught: complete neutral alias heading eligible declaration set")
	}
}
func TestAgreementNeutralAliasHeadingOwnedProjectionRefusals(t *testing.T) {
	for i := range agreementNeutralAliasHeadingDeclarations() {
		r := &agreementNeutralAliasHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			reject := func(s *agreementNeutralAliasHeadingSource, page, privatePage *agreementHTML, ds, pds []render.Diagnostic) {
				t.Helper()
				if agreementNeutralAliasHeadingProjection(s, r.Before, r.After, page, privatePage, ds, pds) {
					t.Fatal("caught: neutral alias heading refuses changed whole projection")
				}
			}
			reject(nil, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			reject(&r.Source, nil, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			reject(&r.Source, &r.Page, nil, r.Diagnostics, r.PrivateDiagnostics)
			s := r.Source
			s.Valid = false
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			s = r.Source
			s.IDs = append(slices.Clone(s.IDs), "outside")
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			s = r.Source
			s.PrivateIDs = append(slices.Clone(s.PrivateIDs), "outside")
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			s = r.Source
			s.Native.Names = maps.Clone(s.Native.Names)
			f := agreementNeutralAliasHeadingSelected(t, r)
			s.Native.Names[f.Fragment] = true
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			pp := r.PrivatePage
			pp.Headings = append(slices.Clone(pp.Headings), "outside")
			reject(&r.Source, &r.Page, &pp, r.Diagnostics, r.PrivateDiagnostics)
			pp = r.PrivatePage
			pp.Citations = append(slices.Clone(pp.Citations), agreementCitation{Target: "outside"})
			reject(&r.Source, &r.Page, &pp, r.Diagnostics, r.PrivateDiagnostics)
			pp = r.PrivatePage
			pp.Blocks = append(slices.Clone(pp.Blocks), "^outside")
			reject(&r.Source, &r.Page, &pp, r.Diagnostics, r.PrivateDiagnostics)
			ds := append(slices.Clone(r.PrivateDiagnostics), render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
			reject(&r.Source, &r.Page, &r.PrivatePage, r.Diagnostics, ds)
		})
	}
}
func TestAgreementNeutralAliasHeadingOwnedPhysicalRefusals(t *testing.T) {
	for i := range agreementNeutralAliasHeadingDeclarations() {
		r := &agreementNeutralAliasHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			f := agreementNeutralAliasHeadingSelected(t, r)
			if agreementNeutralAliasHeadingReading(r.Body, nil, &r.Page).Valid || agreementNeutralAliasHeadingReading(r.Body, &f, nil).Valid {
				t.Fatal("caught: neutral alias heading physical context")
			}
			changes := []func(*agreementFailure){func(f *agreementFailure) { f.Property = "P1" }, func(f *agreementFailure) { f.Identity = "outside" }, func(f *agreementFailure) { f.Fragment = "outside" }, func(f *agreementFailure) { f.Direction = "judge-only" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Tuple.SourceRole = "outside" }, func(f *agreementFailure) { f.Tuple.Target = "outside" }, func(f *agreementFailure) { f.Tuple.Section = "outside" }, func(f *agreementFailure) { f.Tuple.State = "outside" }, func(f *agreementFailure) { f.PagePresent = false }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true }, func(f *agreementFailure) { f.Cut = "outside" }}
			for _, change := range changes {
				x := f
				change(&x)
				if agreementNeutralAliasHeadingReading(r.Body, &x, &r.Page).Valid {
					t.Fatal("caught: neutral alias heading refuses another physical property or signature")
				}
			}
			changed := r.Page
			changed.Headings = append(slices.Clone(changed.Headings), "outside")
			if agreementNeutralAliasHeadingReading(r.Body, &f, &changed).Valid {
				t.Fatal("caught: neutral alias heading refuses altered physical allocation")
			}
		})
	}
}
